<?php
namespace App\Models;
use Database\Factories\UserFactory; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Attributes\Hidden; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable;
#[Fillable(['name','email','phone','password','is_active'])] #[Hidden(['password','remember_token'])]
class User extends Authenticatable { use HasFactory,Notifiable; protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed','is_active'=>'boolean'];} public function roles(){return $this->belongsToMany(Role::class);} public function hasPermission(string $slug):bool{return $this->roles()->whereHas('permissions',fn($q)=>$q->where('slug',$slug))->exists();} public function isAdministrator():bool{return $this->roles()->where('slug','administrator')->exists();} }